	bp::scope().attr( "QUERY_RANKED_BY_UNIQUE_SUBSCRIPTIONS" ) = (int)WORKSHOP_QUERY_RANKED_BY_UNIQUE_SUBSCRIPTIONS;
	bp::scope().attr( "QUERY_RANKED_BY_LAST_UPDATED_DATE" ) = (int)WORKSHOP_QUERY_RANKED_BY_LAST_UPDATED_DATE;

